// --- TEXTURE SCRIPT: OLOGRAFIA REATTIVA ---
// Usa questo script nel dock Texture per un oggetto implicito

// 1. Usiamo lo slider 'A' per controllare la densità della griglia (es. range 0-5)
float gridDensity = 10.0 + (A * 15.0); 

// 2. Creiamo una griglia basata sulle coordinate UV della superficie
// fract() crea il pattern ripetuto, sottraiamo 0.5 per centrare la cella
vec2 grid = fract(uv * gridDensity) - 0.5; 

// 3. Calcoliamo la distanza dai bordi per disegnare le linee
float lineDist = min(abs(grid.x), abs(grid.y));

// 4. Animiamo lo spessore della linea con il tempo 't'
// Lo slider 'B' può controllare la velocità della pulsazione
float pulse = sin(t * (2.0 + B * 5.0));
float thickness = 0.05 + 0.03;

// 5. Creiamo un effetto "Glow" (bagliore) morbido ai bordi della linea
float glow = smoothstep(thickness + 0.05, thickness, lineDist);

// 6. Assegnazione dei colori usando le variabili iniettate dal tuo engine
// Il fondo usa il colore secondario (u_col2), le linee il primario (u_col1) "sparato"
vec3 baseColor = u_col2;                  // Spazio vuoto della griglia (Colore 2)
vec3 neonColor = u_col1 * 1.5;           // Il colore UI, reso più luminoso

// 7. Mixiamo i colori in base al calcolo del glow
vec3 finalColor = mix(baseColor, neonColor, glow);

return finalColor;

