// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 6.28318531;
v_min := 0;
v_max := 6.28318531;
steps := 400;
F := min(1.0);   // camera del path: sotto 1 esce comunque, anche stringendo il FOV

// --- DUE TORI ALLACCIATI, PARAMETRIZZATI LUNGO LE FIBRE DI HOPF ---
// Riscrittura di "Clifford Linked Tori": STESSE due superfici, percorse lungo le
// fibre invece che lungo i meridiani. NB: non dichiarare variabili chiamate
// PI, pi, tau: il traduttore le sostituisce col valore numerico in tutto lo
// script; e nemmeno 's', riservato alla costante S dello slider.
//
// GLI ASSI, come nell'originale: due grandi cerchi che condividono l'indice 1,
//     C12 = (cos s, sin s, 0, 0)        C13 = (cos s, 0, sin s, 0)
// quindi i due tubi di raggio angolare R si toccano nei poli (+-1,0,0,0) e si
// compenetrano in due lenti attorno a quelli: e' cio' che rende i tori
// ALLACCIATI, ed e' il senso del preset.
//
// PERCHE' SERVONO DUE FIBRAZIONI, NON UNA. La fibrazione di Hopf standard
//     J1:  z1 = x1 + i x2,  z2 = x3 + i x4
// ha per fibre C12 e C34 (le fibre sopra i due poli della 2-sfera base). Il
// primo toro, essendo attorno a C12, e' un toro di Hopf per J1: la terza
// componente di h vale cos(2R), costante (misurata: 0.913545 a R = 12 deg).
// Il SECONDO toro invece e' attorno a C13, che NON e' una fibra di J1: lungo C13
// la mappa h VARIA, e sul toro la terza componente spazia da -0.978 a +1. Con la
// sola J1 il secondo toro non ha fibre da seguire.
// La soluzione e' usare per ciascun toro la struttura complessa che rende il suo
// asse una fibra:
//     J1: z1 = x1 + i x2,  z2 = x3 + i x4   -> fibre C12, C34   (toro 1)
//     J2: w1 = x1 + i x3,  w2 = x2 + i x4   -> fibre C13, C24   (toro 2)
// Verificato che h2 e' costante lungo C13, e che sotto J2 il secondo toro ha la
// terza componente costante = cos(2R), esattamente come il primo sotto J1.
// (Alternativa scartata: spostare il secondo toro da C13 a C34, l'altra fibra di
// J1. Cosi' sarebbero entrambi tori di Hopf della stessa fibrazione, ma C12 e
// C34 sono complementari, quindi i due tori risulterebbero CONCENTRICI e
// ANNIDATI, a distanza 1.09 l'uno dall'altro: disgiunti, mai allacciati. Il
// preset perderebbe il suo oggetto. Per quel caso c'e' "Hopf Tori over
// Parallels".)
//
// LA RIPARAMETRIZZAZIONE. Passare dai meridiani alle fibre e' la sostituzione
//     phi -> phi + sfib
// nel primo fattore: raddrizza le diagonali (1,1) della griglia sulle linee
// u = costante. L'INSIEME di punti non cambia (verificato: 3600 punti su 3600
// coincidono con l'originale, per entrambi i tori), cambia solo come lo si
// percorre. Effetto visibile: le linee del wireframe a v costante SONO le fibre
// di Hopf, grandi cerchi di S^3 (centro nell'origine, raggio 1.000000) che in
// stereografica appaiono come cerchi di Villarceau allacciati a due a due.
//
// --- APERTURA SULLO SLIDER F ---
// F e' il raggio angolare dei tubi in passi di 4.5 gradi (PI/40), come negli
// altri preset della famiglia:
//     F = 2.67 -> 12 gradi (il valore storico)   F = 10 -> PI/4 = 45 gradi
// Il minimo e' 1 e non 0.3 perche' c'e' un path: comanda il cono VISIVO della
// camera, che a uno snodo interseca la parete opposta mentre il tubo curva.
// Sta su F e non su A o B perche' quelle pilotano lo sfondo CRT.
//
// --- MULTI-MESH: un toro per griglia ---
// `mesh` vale 0 sul primo toro e 1 sul secondo. Con una griglia sola servivano
// v su [0,4*PI], step(6.28318,v) per scegliere il ramo, il riscalamento f1/f2
// per chiudere il tubo a cui mancava un passo, e una banda di guardia nel cutout
// per scartare il quad di giunzione (che lasciava un solco circolare). Con due
// mesh separate nessun quad puo' collegarle: tutto sparito.
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END
//MESH_BEGIN
u: 0, 6.28318531, 200
v: 0, 6.28318531, 200
//MESH_END

float R = clamp(F, 1.0, 10.0) * 0.078539816;

float cR = cos(R);
float sR = sin(R);

// sel = 0 sul toro attorno a C12, 1 su quello attorno a C13.
float sel = mesh;

// Coordinate di fibra: u corre lungo la fibra, v lungo il parallelo della base.
// 'sfib' e non 's': quel nome e' riservato alla costante S dello slider, che il
// motore inietta come `float s` in ogni script -> "'s' : redefinition".
float sfib = u;
float phi = v;

// Fattore grande (raggio cos R) sul piano dell'asse, ruotato di phi+sfib;
// fattore piccolo (raggio sin R) sul piano complementare, ruotato di sfib.
float big1 = cR * cos(phi + sfib);
float big2 = cR * sin(phi + sfib);
float sml1 = sR * cos(sfib);
float sml2 = sR * sin(sfib);

// Toro 1 (J1, asse C12): (x1,x2) = fattore grande, (x3,x4) = fattore piccolo.
// Toro 2 (J2, asse C13): (x1,x3) = fattore grande, (x2,x4) = fattore piccolo,
// cioe' le componenti 2 e 3 si scambiano — la stessa trasposizione che
// l'originale applicava ai meridiani.
// NB: il validatore in inputvalidator.cpp pretende la forma letterale del return
// con vec3 o vec4 aperto subito dopo: assegnare a una variabile e restituirla
// viene RIFIUTATO. Inoltre conta le parentesi su tutto il testo, COMMENTI
// INCLUSI: non scriverne di spaiate qui.
return vec4(
    big1,
    mix(big2, sml1, sel),
    mix(sml1, big2, sel),
    sml2
);

//CUTOUT_BEGIN
// --- TAGLIO DELLE COMPENETRAZIONI ---
// Da ogni toro si rimuove la parte che sta dentro il volume dell'altro: e' il
// bordo dell'unione dei due solidi. Criterio ESATTO in forma chiusa, senza
// ricerca numerica: un punto sta dentro il tubo di raggio R attorno a C_ij se la
// sua distanza angolare da quel cerchio e' < R, e vale acos(sqrt(xi^2 + xj^2)):
//     dentro il toro 1 (C12)  <=>  sqrt(x1^2 + x2^2) > cos R
//     dentro il toro 2 (C13)  <=>  sqrt(x1^2 + x3^2) > cos R
// Il criterio e' sull'INSIEME di punti, quindi NON dipende dalla
// parametrizzazione: vale identico in coordinate di fibra (verificato: taglia
// l'8.86% di ciascun toro, come nella versione a meridiani).
// stesso raggio del corpo, dallo stesso slider: se le due copie divergessero il
// taglio non cadrebbe piu' sulla superficie che ritaglia
float Rc = clamp(F, 1.0, 10.0) * 0.078539816;
float cRc = cos(Rc);
float sRc = sin(Rc);

float selc = mesh;

float sfc = u;
float phc = v;

float bg1 = cRc * cos(phc + sfc);
float bg2 = cRc * sin(phc + sfc);
float sm1 = sRc * cos(sfc);
float sm2 = sRc * sin(sfc);

// ricostruisce il punto di QUESTO frammento, come nel corpo
float px = bg1;
float py = mix(bg2, sm1, selc);
float pz = mix(sm1, bg2, selc);

// ogni toro si testa contro l'ALTRO: il toro 1 contro C13 (indici 1,3), il
// toro 2 contro C12 (indici 1,2).
float radial = mix(sqrt(px * px + pz * pz), sqrt(px * px + py * py), selc);

// Resta SOLO il criterio geometrico: sparite la banda di guardia sulla
// cucitura, il riscalamento f1/f2 e il calcolo di passo, perche' con due mesh
// separate non esiste piu' nessun quad di giunzione da mascherare.
return (radial > cRc);
//CUTOUT_END

